import '../components/boon-product-indicator.js';
import '../components/quest-objective-indicator.js';

// These are mirrors of the native action controls. The components subscribe to
// existing store data; mounting the overview must not trigger more chain reads.
const tiles = [
  ['[data-dgx-kind="tickets"]', ['purchase'], ['purchase', 'foil']],
  ['[data-dgx-kind="passes"]', ['whale', 'lazy', 'deity'], []],
  ['[data-dgx-kind="luckboxes"]', ['lootbox'], ['lootbox']],
  ['.site-degenerette-cell', ['degenerette-eth', 'degenerette-flip'], ['degenerette-eth', 'degenerette-flip']],
  ['.site-craps-cell', ['craps'], []],
];

export function mountProductIndicators(board) {
  for (const [selector, boons, quests] of tiles) {
    const tile = board?.querySelector(selector);
    if (!tile || tile.querySelector('.site-tile-indicators')) continue;
    const row = document.createElement('span');
    row.className = 'site-tile-indicators';
    for (const [tag, products] of [['boon-product-indicator', boons], ['quest-objective-indicator', quests]]) {
      for (const product of products) {
        const marker = document.createElement(tag);
        marker.setAttribute('product', product);
        if (tag === 'boon-product-indicator') marker.setAttribute('passive', '');
        row.append(marker);
      }
    }
    tile.append(row);
  }
}
